$path='C:\Users\pc\Desktop\TheBlackLilyBloomsinHerEyes\chinese-patch\source\data\scenario\zh-CN\story\chapter2s2.ks'
$m=@{
'#壱十'='#壹十'; '#ひとみ'='#瞳'; '#世界'='#世界'; '#例ちゃん先輩'='#例前辈';
23='「对了。到达之前，还是先联系例前辈比较好吧。」[p]';25='算上在公园睡着的时间，离开咖啡店已经快两个小时了。[p]';26='例前辈和老板住在咖啡店里，应该不会不在，但时间已经很晚，还是应该先打声招呼。[p]';27='更何况，一个本该下班的兼职员工在跨日之前突然回来，他们也会觉得发生了什么吧。[p]';31='「啊――理由该怎么说呢？」[p]';33='对那两人来说，就算我只说突然想见见他们的脸，应该也会接受。[p]';34='不过，如果理由太过含糊，他们或许会猜测我是不是离家出走了。[p]';35='我不想让他们徒增担心，可也不能老老实实告诉他们什么魔法之类的事。[p]';36='实际上，我并不太担心就算说了他们也不相信――[p]';37='恰恰相反，那个接受了例前辈特殊性――接受“例外存在”概念的地方，[p]';38='恐怕会把魔法当作现实认真对待，所以才不能说。[p]';39='一旦知道这是个能实现愿望、可疑又危险至极的仪式，那两个有常识的人一定会试图把我从魔法中拉开。[p]';40='对正想抓住那万分之一可能性的我来说，现在接受大人的介入并不是本意。[p]';45='「要不就说忘了东西，稳妥一点？」[p]';47='也可以，但我根本没忘东西……这种谎话未免太容易被识破了。[p]';50='「嗯……说到底，壹十你打算去咖啡店做什么？」[p]';51='「如果目的是和例前辈或老板谈话，那魔法这个话题果然躲不过去吧……？」[p]';53='理想情况是，在不让对方察觉真实意图的前提下套出魔法的情报……[p]';54='但正如瞳所说，既然我连去咖啡店要做什么都还没决定，[p]';55='或许比起编造虚假理由，更应该先考虑真正的理由。[p]';56='虽然我是凭直觉开始走的，但事后也应该给自己找一个理性的动机。[p]';57='只要看清理由，行动方针也会确定。那就是让她――让宵星瞳复活的道路。[p]';59='然而――――[p]';64='正如我们开始行动，其他玩家也都在依照各自的想法行动。[p]';65='世界没有慢到能给予我们充分思考的时间。[p]';67='「壹十，铃响了！」[p]';70='「啊，我知道！两声、三声――也就是说，某个铃之持有者正以惊人的速度朝我们――」[p]';74='「――哟，大哥。往那个方向去是有什么事吗？」[p]';79='那个存在仿佛在嘲笑四处寻找敌影的我，堂堂正正地降落在道路正中央。[p]';80='路灯照耀下，一个双腿叉开站立的女人显露身形。[p]';81='映入眼帘的是一位拥有凌厉锋芒与鲜明美貌、暴烈得近乎暴力却又极具魅力的美女。[p]';82='直觉在低语。理性与本能从两个方向强行让我理解。[p]';83='这个人也是同样的铃之持有者。然后――[p]';94='在脑海中掠过的迟钝噪音深处，我感受到的那个会把我彻底击溃、绝对无法超越的存在，正是这个女人。[p]';95='为什么能察觉一个连脸和名字都不知道的对手？难道是不知不觉感受到了她强大得过分、如同气场般的压迫感？[p]';96='无论如何，察觉到她的过程已经不重要。[p]';97='现在重要的是结果――在还来得及挽回的阶段，不要做出错误选择。[p]';98='只要走错一步，我们就会在这里失去一切、迎来终结。[p]';101='「……我正准备去前面那家咖啡店。」[p]';104='「哦？这么晚了，店应该已经关门了吧？」[p]';106='「嗯，我知道。我就在那家咖啡店工作。」[p]';108='「原来是兼职小哥。那这个本该下班的兼职小哥，回店里有什么事？」[p]';110='冷汗从额头滑落，舌根渐渐发干。[p]';111='每编织出一个句节，我都能切身感到声音与存在的重压不断增加。[p]';112='问题没有改变。从一开始，她始终如一地要求我――回答来意。[p]';114='「――时宫壹十。」[p]';117='「……啊？」[p]';119='「不是兼职小哥，那是我的名字。」[p]';120='「我去咖啡店的理由是――要和例前辈谈谈魔法。」[p]';122='我在仿佛永恒般的[ruby text="しゅゆ"]须臾间思考过后，决定坦白目的。[p]';123='恐怕谎言和花招对这个人不起作用。[p]';124='既然如此，趁我们还勉强没有敌对――趁还能与她对视，正面面对她才是上策。[p]';126='那位红发美女沉默片刻，露出锐利的犬齿，[p]';129='「……咔哈哈哈哈！」[p]';131='「哎呀，不错嘛！比例前辈说的还要有胆量。」[p]';133='她的豪迈笑声响彻寂静的住宅区，随后迈开大步破风走来，[p]';136='像要将我整个罩住般，结结实实地搂住了我的肩膀。[p]';138='「我是[ruby text="かみうえぞの"]神上园[ruby text="せかい"]世界。刚才试探你，抱歉了。我挺喜欢你的。」[p]';140='「……谢谢。看来你果然也认识例前辈。」[p]';143='「当然。例前辈可是我的铁哥们，所以当然也听说过你的事。」[p]';145='铁哥们这种说法，别说现在了，就算十年前也该是过时的词了吧。[p]';147='「不过，在我听说的时宫壹十里，你本来应该只是个连魔法都一无所知的普通人。」[p]';149='「那神上园小姐也――」[p]';152='「叫我世界。用名字，别叫姓氏。」[p]';154='她的声音突然低了一个音调，缠住我脖子的手臂也加重了一分力道。[p]';155='单纯来说，这压力很可怕。我仿佛听见被她抓住的肩骨发出扭曲的声响。[p]';157='「――世界小姐也知道吧？现在这座城里发生的仪式。」[p]';160='「当然。听你这口气……你是想说，自己因为被卷入那个仪式，才知道魔法的存在？」[p]';162='「就是这样。」[p]';164='我没有说半句谎话。被卷入莫名的神秘事件、在那里第一次知道魔法存在，都是事实。[p]';165='不过，没必要把那之后的愿望也说出来。[p]';166='她知道仪式已经开始。[p]';167='也就是说，神上园世界和我、以及在公园遇到的那个男人一样，都是铃之持有者――迟早必须打倒的存在。[p]';169='「嗯嗯……大概算是摸清现状了。」[p]';171='也许从我的回答中得到了什么确认，世界小姐满意地松开搭在我肩上的手，背过身朝前走去。[p]';173='「呃……你要去哪儿？」[p]';176='「去哪？当然是去咖啡店吧？」[p]';178='她以理所当然的表情回头，带着与她十分相称的冷笑说道，[p]';181='「走吧，新人。我来教你什么叫魔法。」[p]';202='「你开始在那家咖啡店工作多久了？」[p]';205='「半年多一点吧。」[p]';208='「还不错。你知道咖啡店“异常”和魔法有关吗？」[p]';211='「不知道。说到底，我连魔法存在都不知道。」[p]';214='「哦？那你或许是凭感觉察觉到了。或者，是从例前辈的“例外”联想到的吧。」[p]';217='「世界小姐和例前辈，都是魔术师吧？」[p]';220='「算是吧。例前辈的立场有点特殊，但广义来说，我和她都是魔术师。」[p]';223='「魔术师有很多人吗？」[p]';226='「占全人类的比例确实很少。不过，应该比你想象的多得多。」[p]';227='「只是大多数魔术师都会隐藏魔法力量，融入普通社会，所以即使就在身边，你也几乎察觉不到。」[p]';230='「就像老板和例前辈隐藏起来那样。」[p]';233='「那家咖啡店也兼任连接表社会与魔法社会的窗口。」[p]';234='「魔法不是公开知识，所以大多数时候都会伪装成那种普通店铺。」[p]';237='「那老板为什么会雇用不是魔术师的我？」[p]';240='「谁知道呢，你直接去问他吧。看，马上就到了。」[p]'
}
$lines=[System.Collections.Generic.List[string]](Get-Content $path -Encoding UTF8)
foreach($n in $m.Keys){ if($n -is [int]){$lines[$n-1]=$m[$n]} else { for($i=0;$i -lt $lines.Count;$i++){if($lines[$i] -eq $n){$lines[$i]=$m[$n]}}}}
[IO.File]::WriteAllLines($path,$lines,[Text.UTF8Encoding]::new($false))
